-- Use the palette generated by Solace/Aether rather than a separate editor theme.
local theme_file = vim.fn.expand("~/.config/solace/current/theme/neovim.lua")
local specs = dofile(theme_file)

local transparent_groups = {
  "Normal",
  "NormalNC",
  "NormalFloat",
  "FloatBorder",
  "Pmenu",
  "Terminal",
  "EndOfBuffer",
  "FoldColumn",
  "Folded",
  "SignColumn",
  "LineNr",
  "CursorLineNr",
}

local function transparency()
  for _, name in ipairs(transparent_groups) do
    local hl = vim.api.nvim_get_hl(0, { name = name, link = false })
    hl.bg = nil
    vim.api.nvim_set_hl(0, name, hl)
  end
end

for _, spec in ipairs(specs) do
  if spec[1] ~= "LazyVim/LazyVim" then
    spec.lazy = false
    spec.init = function()
      local group = vim.api.nvim_create_augroup("SolaceTheme", { clear = true })
      vim.api.nvim_create_autocmd("ColorScheme", {
        group = group,
        callback = transparency,
      })
      vim.api.nvim_create_autocmd("User", {
        group = group,
        pattern = "LazyReload",
        callback = function()
          vim.schedule(function()
            local current = dofile(theme_file)
            for _, theme in ipairs(current) do
              if theme[1] == "bjarneo/aether.nvim" then
                require("aether").setup(theme.opts or {})
                vim.cmd.colorscheme("aether")
                vim.cmd.redraw()
              end
            end
          end)
        end,
      })
    end
  end
end

return specs
